//! Derived media used by the timeline: filmstrip thumbnails and audio peaks.
//!
//! Both are generated by ffmpeg and cached under the project's cache directory,
//! keyed by a content hash so a re-import or a re-probe never re-does the work.

use crate::model::{Micros, Waveform, ONE_SECOND};
use crate::probe::ffmpeg_bin;
use anyhow::{bail, Context, Result};
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

/// Decode rate for peak extraction. 8 kHz mono is far more resolution than any
/// timeline can display and keeps the working set small.
const PEAK_SAMPLE_RATE: u32 = 8_000;

/// Render a single frame of `src` at `at` into `dest` as JPEG.
///
/// A still image has exactly one frame, so seeking into it yields nothing — and
/// ffmpeg exits *successfully* while writing no file. The output is therefore
/// checked, and an empty result is retried from the start rather than reported
/// as a thumbnail that does not exist.
pub fn write_thumbnail(src: &Path, at: Micros, width: u32, dest: &Path) -> Result<()> {
    if let Some(parent) = dest.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let _ = std::fs::remove_file(dest);

    if render_frame(src, at, width, dest).is_ok() && is_non_empty(dest) {
        return Ok(());
    }
    if at > 0 && render_frame(src, 0, width, dest).is_ok() && is_non_empty(dest) {
        return Ok(());
    }
    let _ = std::fs::remove_file(dest);
    bail!("génération de vignette échouée: aucune image produite");
}

fn is_non_empty(path: &Path) -> bool {
    std::fs::metadata(path)
        .map(|m| m.len() > 0)
        .unwrap_or(false)
}

fn render_frame(src: &Path, at: Micros, width: u32, dest: &Path) -> Result<()> {
    let seconds = at as f64 / ONE_SECOND as f64;
    let out = Command::new(ffmpeg_bin())
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        // Seeking before -i makes this a keyframe seek: fast, and good enough
        // for a poster frame.
        .args(["-ss", &format!("{seconds:.3}")])
        .arg("-i")
        .arg(src)
        .args(["-frames:v", "1"])
        .args(["-vf", &format!("scale={width}:-2")])
        // Full-range sources (screen captures, PNGs) make the mjpeg encoder fail
        // with "Non full-range YUV is non-standard". Asking for full-range output
        // is the fix; without it, importing an image fails outright.
        .args(["-pix_fmt", "yuvj420p"])
        .args(["-q:v", "4"])
        .arg(dest)
        .output()
        .context("lancement de ffmpeg pour la vignette impossible")?;
    if !out.status.success() {
        bail!(
            "génération de vignette échouée: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        );
    }
    Ok(())
}

/// Extract `buckets` min/max peak pairs from the audio of `src`.
///
/// `expected_duration` comes from the probe and only decides where bucket
/// boundaries fall; the stream itself is decoded incrementally so a two-hour
/// podcast never has to be buffered in memory in one piece.
pub fn extract_waveform(src: &Path, expected_duration: Micros, buckets: usize) -> Result<Waveform> {
    let buckets = buckets.max(1);
    let mut child = Command::new(ffmpeg_bin())
        .args(["-hide_banner", "-loglevel", "error", "-i"])
        .arg(src)
        .args([
            "-vn",
            "-ac",
            "1",
            "-ar",
            &PEAK_SAMPLE_RATE.to_string(),
            "-f",
            "f32le",
            "-",
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .context("lancement de ffmpeg pour la forme d'onde impossible")?;

    let mut stdout = child.stdout.take().context("stdout ffmpeg indisponible")?;
    let total_samples = ((expected_duration as f64 / ONE_SECOND as f64) * PEAK_SAMPLE_RATE as f64)
        .round()
        .max(1.0) as u64;
    let samples_per_bucket = (total_samples as f64 / buckets as f64).max(1.0);

    let mut peaks: Vec<(f32, f32)> = vec![(0.0, 0.0); buckets];
    let mut bucket_filled = vec![false; buckets];
    let mut buf = vec![0u8; 64 * 1024];
    let mut index: u64 = 0;

    loop {
        let read = stdout.read(&mut buf)?;
        if read == 0 {
            break;
        }
        // `as_chunks` states the frame size in the type system, so the four
        // bytes cannot drift out of sync with the conversion below.
        for chunk in buf[..read].as_chunks::<4>().0 {
            let sample = f32::from_le_bytes(*chunk);
            if !sample.is_finite() {
                index += 1;
                continue;
            }
            let b = ((index as f64 / samples_per_bucket) as usize).min(buckets - 1);
            let peak = peaks[b];
            peaks[b] = (peak.0.min(sample), peak.1.max(sample));
            bucket_filled[b] = true;
            index += 1;
        }
    }

    let status = child.wait()?;
    if !status.success() {
        let mut err = String::new();
        if let Some(mut s) = child.stderr.take() {
            let _ = s.read_to_string(&mut err);
        }
        bail!("extraction de forme d'onde échouée: {}", err.trim());
    }

    // A file with no audio track produces nothing: report silence rather than
    // a misleading flat-but-present waveform.
    if !bucket_filled.iter().any(|f| *f) {
        return Ok(Waveform {
            samples_per_bucket: 0,
            peaks: Vec::new(),
        });
    }

    Ok(Waveform {
        samples_per_bucket: samples_per_bucket as u32,
        peaks,
    })
}

/// Content-addressed cache directory for derivatives.
pub fn cache_dir(root: &Path) -> PathBuf {
    root.join(".clipcache")
}

#[cfg(test)]
mod tests {
    #[test]
    fn bucket_math_covers_the_stream() {
        let total = 8_000u64 * 10; // ten seconds
        let buckets = 100usize;
        let per = (total as f64 / buckets as f64).max(1.0);
        assert!((per - 800.0).abs() < f64::EPSILON);
    }
}
